// Généré par scripts/build-content.mjs — ne pas modifier
export const COURS: Record<string, string> = {"numeration":"\n<section class=\"ecran\"><h2>1. Faire des paquets de 10 <span class=\"lv lv-CE1\">CE1</span></h2>\n<p><img src=\"figures/numeration/materiel.svg\" alt=\"10 cubes font une barre, 10 barres font une plaque\"></p>\n<p>Compter un par un, c&#39;est long.\nAlors on fait des <strong>paquets de 10</strong>.</p>\n<blockquote>\n<p><strong>Exemple.</strong> 4 barres et 7 cubes : <span class=\"nw\">40 + 7</span> = <strong>47</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"echanger\"></div></section><section class=\"ecran\"><h2>2. Chaque chiffre a sa place <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/numeration/tableau.svg\" alt=\"352 dans le tableau : 300, 50 et 2\"></p>\n<p>Un chiffre vaut plus ou moins selon <strong>sa colonne</strong>.\nLe <strong>0</strong> garde une place vide.</p>\n<p><span class=\"lv lv-CE2\">CE2</span> Une colonne de plus à gauche : les <strong>milliers</strong>.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <strong>407</strong>, c&#39;est 4 centaines, <strong>0</strong> dizaine, 7 unités. Pas 47 !</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"tableau\"></div></section><section class=\"ecran\"><h2>3. Chiffre ou nombre de dizaines ? <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/numeration/dizaines.svg\" alt=\"Dans 352 : chiffre des dizaines 5, nombre de dizaines 35\"></p>\n<p>Le <strong>chiffre</strong> des dizaines, c&#39;est un seul chiffre.\nLe <strong>nombre</strong> de dizaines compte aussi les centaines.</p>\n<blockquote>\n<p><strong>Exemple.</strong> Dans 352, il y a <strong>35</strong> dizaines.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"dizaines\"></div></section><section class=\"ecran\"><h2>4. Échanger et décomposer <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/numeration/echange.svg\" alt=\"10 unités contre 1 dizaine ; 635 écrit de 4 façons\"></p>\n<p>10 unités ⇄ 1 dizaine : on échange dans les deux sens.\nLe nombre ne change pas.</p>\n<blockquote>\n<p><strong>Exemple.</strong> 2 centaines, <strong>15</strong> dizaines, 4 unités.\n10 dizaines → 1 centaine. Donc <strong>354</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"echanger\"></div></section><section class=\"ecran\"><h2>5. Comparer et ranger <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/numeration/comparer.svg\" alt=\"Comparer 243 et 239 de gauche à droite\"></p>\n<p>Plus de chiffres ? Plus grand : 1 009 &gt; 999.\nSinon, compare <strong>de gauche à droite</strong>.</p>\n<blockquote>\n<p><strong>Exemple.</strong> Encadrer : 470 &lt; <strong>476</strong> &lt; 480.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"ranger\"></div></section><section class=\"ecran\"><h2>6. La demi-droite graduée <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/numeration/droite.svg\" alt=\"3 sauts de 10 après 470 : 500\"></p>\n<p>D&#39;abord, trouve <strong>le pas</strong>.\nPuis compte les <strong>sauts</strong>, pas les traits.</p>\n<p><span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span> Pareil avec de grands pas : 10 000, 100 000…</p>\n<div class=\"go-exo\" data-exos=\"droite lire\"></div></section><section class=\"ecran\"><h2>7. Compter de n en n <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/numeration/bande.svg\" alt=\"375, 385, 395, 405 : on avance de 10\"></p>\n<p>On avance toujours du <strong>même pas</strong>.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">395 + 10</span> = <strong>405</strong>. Pas « 3 105 » !</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"suites\"></div></section><section class=\"ecran\"><h2>8. Les grands nombres <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span> <span class=\"lv lv-6e\">6e</span></h2>\n<p><img src=\"figures/numeration/classes.svg\" alt=\"2 030 004 en classes de 3 chiffres\"></p>\n<p>Coupe le nombre en <strong>classes</strong> de 3 chiffres, depuis la droite.</p>\n<p><span class=\"lv lv-CM1\">CM1</span> jusqu&#39;à 999 999 · <span class=\"lv lv-CM2\">CM2</span> jusqu&#39;au milliard · <span class=\"lv lv-6e\">6e</span> les milliards</p>\n<blockquote>\n<p><strong>Exemple.</strong> cinq-cent-mille-douze → 500 <strong>012</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"grands\"></div></section><p><em>Sources d&#39;inspiration : programmes du cycle 2 (BO n° 41 du 31/10/2024) et du cycle 3 (BO n° 16 du 17/04/2025), ressources d&#39;accompagnement eduscol, matériel multibase popularisé par la MHM et la méthode de Singapour. Textes et figures originaux.</em></p>\n","addition":"\n<section class=\"ecran\"><h2>1. Ajouter ou enlever ? <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/addition/situations.svg\" alt=\"Le tout, une partie, le début, l&#39;écart\"></p>\n<p>Avant de calculer, imagine l&#39;histoire.\nQue cherches-tu ?</p>\n<blockquote>\n<p><strong>Exemple.</strong> J&#39;ai donné 56 images. Il m&#39;en <strong>reste</strong> 217. Au début ? <span class=\"nw\">217 + 56</span> = <strong>273</strong>. On ajoute !</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"probadd\"></div></section><section class=\"ecran\"><h2>2. Attention aux mots <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/addition/mots.svg\" alt=\"Léa a 15 €, 6 € de plus que Noé\"></p>\n<p>« De plus » ne veut pas toujours dire +.\n« Il reste » ne veut pas toujours dire −.</p>\n<blockquote>\n<p><strong>Exemple.</strong> 83 livres, on en apporte 18, on en emprunte 27 : <span class=\"nw\">83 + 18 − 27</span> = <strong>74</strong>. L&#39;âge du bibliothécaire ne sert à rien !</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"probadd\"></div></section><section class=\"ecran\"><h2>3. Les compléments <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/addition/complements.svg\" alt=\"De 64 à 100 : + 6, puis + 30\"></p>\n<p>Le complément, c&#39;est ce qui <strong>manque</strong>.\n7 + <strong>3</strong> = 10.</p>\n<blockquote>\n<p><strong>Exemple.</strong> 4 + <strong>?</strong> = 12. Il manque <strong>8</strong>. Vérifie : <span class=\"nw\">4 + 8 = 12</span>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"complements\"></div></section><section class=\"ecran\"><h2>4. Passer par la dizaine <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p><img src=\"figures/addition/sauts.svg\" alt=\"47 + 8 en deux sauts\"></p>\n<p>Va d&#39;abord à la dizaine.\nPuis finis le saut.</p>\n<p><span class=\"lv lv-CM1\">CM1</span> <span class=\"nw\">746 + 80</span> : pense en dizaines. 74 d + 8 d = 82 d → <strong>826</strong>.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">523 − 7</span> : 523 → 520 → <strong>516</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"mental\"></div></section><section class=\"ecran\"><h2>5. + 9 et − 9 <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p><img src=\"figures/addition/neuf.svg\" alt=\"36 + 9 : + 10, puis − 1\"></p>\n<p>+ 9, c&#39;est + 10, puis − 1.</p>\n<p>− 9, c&#39;est − 10, puis + 1.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">53 − 9 = 43 + 1</span> = <strong>44</strong>. Pareil : + 19 = + <span class=\"nw\">20 − 1</span>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"mental\"></div></section><section class=\"ecran\"><h2>6. L&#39;addition posée <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p><img src=\"figures/addition/addition.svg\" alt=\"245 + 437 posée, avec la retenue\"></p>\n<p>Les unités sous les unités. Commence <strong>à droite</strong>.\n12 unités ? J&#39;écris 2, la dizaine monte : c&#39;est la <strong>retenue</strong>.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">76 + 7 + 568</span>. Unités : <span class=\"nw\">6 + 7 + 8 = 21</span>, j&#39;écris 1, je retiens 2. Résultat : <strong>651</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"addpose\"></div></section><section class=\"ecran\"><h2>7. La soustraction posée <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p><img src=\"figures/addition/soustraction.svg\" alt=\"52 − 27 : je casse, ou je compense\"></p>\n<p><span class=\"nw\">2 − 7</span> ? Pas assez d&#39;unités en haut.\nDeux façons, <strong>au choix</strong> : les deux sont justes.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">52 − 27</span> = <strong>25</strong>. Vérifie : <span class=\"nw\">25 + 27 = 52</span> ✔</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"subpose\"></div></section><section class=\"ecran\"><h2>8. Le piège du zéro <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p><img src=\"figures/addition/zero.svg\" alt=\"403 − 158 : casser une centaine\"></p>\n<p>Pas de dizaine à casser ?\nCasse d&#39;abord une centaine.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">403 − 158</span> = <strong>245</strong>. Vérifie : <span class=\"nw\">245 + 158 = 403</span> ✔</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"subpose\"></div></section><p><em>Sources d&#39;inspiration : programme du cycle 2 (BO n° 41 du 31/10/2024), ressources d&#39;accompagnement eduscol. Textes et figures originaux.</em></p>\n","multiplication":"\n<section class=\"ecran\"><h2>1. Des paquets pareils <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/multiplication/paquets.svg\" alt=\"7 paquets de 20 biscuits : 7 × 20\"></p>\n<p>Plusieurs fois <strong>la même quantité</strong> ? On multiplie.\nOn lit « 7 <strong>fois</strong> 20 ».</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">3 × 4 = 4 + 4 + 4</span> = <strong>12</strong>. Pas <span class=\"nw\">3 + 4</span> !</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"probmul\"></div></section><section class=\"ecran\"><h2>2. Le rectangle, et le tourner <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/multiplication/rectangle.svg\" alt=\"3 rangées de 4, puis tourné : 4 rangées de 3\"></p>\n<p>Des rangées pareilles : c&#39;est un rectangle.\nTourne-le : mêmes carreaux, même produit.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">2 × 9</span> ? Fais plutôt <span class=\"nw\">9 × 2 = 9 + 9</span> = <strong>18</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"rectangle\"></div></section><section class=\"ecran\"><h2>3. Les tables <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/multiplication/tables.svg\" alt=\"Les astuces des tables\"></p>\n<p>Apprends-les par cœur, dans les <strong>deux sens</strong> : 6 × <strong>?</strong> = 42.\nUn trou de mémoire ? Reconstruis avec une astuce.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">0 × 7</span> = <strong>0</strong> : zéro fois, rien. <span class=\"nw\">1 × 7</span> = <strong>7</strong> : une seule fois.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"tables\"></div></section><section class=\"ecran\"><h2>4. Découper le rectangle <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/multiplication/decoupe.svg\" alt=\"7 × 8 = 7 × 5 + 7 × 3\"></p>\n<p>Coupe en deux morceaux faciles.\nLes carreaux ne disparaissent pas.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">6 × 7 = 6 × 5 + 6 × 2 = 30 + 12</span> = <strong>42</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"tables\"></div></section><section class=\"ecran\"><h2>5. Doubles et moitiés <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/multiplication/doubles.svg\" alt=\"Double de 35 = 70, moitié de 70 = 35\"></p>\n<p>Le <strong>double</strong>, c&#39;est 2 fois. La <strong>moitié</strong>, c&#39;est 2 parts égales.\nCoupe le nombre en morceaux faciles.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">25 + 25 = 50</span>, et <span class=\"nw\">4 × 25</span> = <strong>100</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"doubles\"></div></section><section class=\"ecran\"><h2>6. × 10, × 100, × 1 000 <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/multiplication/glisse.svg\" alt=\"72 × 10 = 720 dans le tableau\"></p>\n<p>× 10 : chaque chiffre monte d&#39;<strong>un rang</strong>.\n× 100 : deux rangs. × 1 000 : trois rangs.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">34 × 100</span> = <strong>3 400</strong>. « Ajouter des 0 » marche, mais c&#39;est le rang qui compte.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"fois10\"></div></section><section class=\"ecran\"><h2>7. La multiplication posée <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/multiplication/posee.svg\" alt=\"548 × 16 posée\"></p>\n<p>Une ligne par chiffre du bas.\nLe 1 de 16 vaut <strong>10</strong> : la 2e ligne finit par 0.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">43 × 6 = 240 + 18</span> = <strong>258</strong>. Mets en bas le nombre qui a le moins de chiffres.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"mulpose\"></div></section><section class=\"ecran\"><h2>8. Les multiples <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/multiplication/multiples.svg\" alt=\"Les multiples de 5 sur la droite\"></p>\n<p>Un multiple de 5 est dans la <strong>table de 5</strong>.\nLes nombres <strong>pairs</strong> sont les multiples de 2. Les autres sont <strong>impairs</strong>.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">75 = 3 × 25</span> : multiple de 25. Mais 3 n&#39;est <strong>pas</strong> un multiple de 6 : c&#39;est un <strong>diviseur</strong> de 6.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"multiples\"></div></section><p><em>Sources d&#39;inspiration : programme du cycle 2 (BO 2024 : sens, commutativité, tables dans les deux sens, × 10 et glisse-nombres, multiplication posée en période 4 du CE2), programme du cycle 3, ressources eduscol. Textes et figures originaux.</em></p>\n","division":"\n<section class=\"ecran\"><h2>1. Partager équitablement <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/division/partager.svg\" alt=\"12 images pour 3 enfants : 4 chacun\"></p>\n<p>Partager équitablement : chacun a <strong>autant</strong>.\nOn donne un à chacun, puis encore un.</p>\n<p><span class=\"lv lv-CE2\">CE2</span> On écrit <span class=\"nw\">12 ÷ 3 = 4</span>. On lit « 12 divisé par 3 ».</p>\n<blockquote>\n<p><strong>Exemple.</strong> 18 images pour 3 enfants : <strong>6</strong> chacun.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"partage\"></div></section><section class=\"ecran\"><h2>2. Faire des groupes <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p><img src=\"figures/division/groupes.svg\" alt=\"12 élèves en équipes de 3 : 4 équipes\"></p>\n<p>Combien de groupes de 3 dans 12 ?\nFais les groupes, puis compte-les.</p>\n<blockquote>\n<p><strong>Exemple.</strong> 24 élèves, équipes de 4 : <strong>6</strong> équipes.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"partage\"></div></section><section class=\"ecran\"><h2>3. La division et les tables <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/division/famille.svg\" alt=\"24 ÷ 4 et 4 × 6 ; la famille 7, 13, 91\"></p>\n<p>Pour <span class=\"nw\">24 ÷ 4</span>, cherche : 4 fois combien font 24 ?\nMultiplier et diviser vont ensemble.</p>\n<blockquote>\n<p><strong>Exemple.</strong> 4 × <strong>6</strong> = 24, donc <span class=\"nw\">24 ÷ 4</span> = <strong>6</strong>. Vérifie toujours avec une multiplication.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"famille\"></div></section><section class=\"ecran\"><h2>4. Le reste <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/division/reste.svg\" alt=\"17 billes pour 5 enfants : 3 chacun, reste 2\"></p>\n<p>Ça ne tombe pas juste ? Ce qui reste, c&#39;est le <strong>reste</strong>.\nIl est toujours plus petit que le diviseur.</p>\n<blockquote>\n<p><strong>Exemple.</strong> Il reste 7 billes pour 5 enfants ? Donne encore une bille à chacun !</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"reste\"></div></section><section class=\"ecran\"><h2>5. Que faire du reste ? <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/division/probreste.svg\" alt=\"189 photos : 19 pages ; 75 œufs : 12 boîtes pleines\"></p>\n<p>Lis bien la question.\n<strong>Toutes</strong> les photos ? Des boîtes <strong>pleines</strong> ? Ce qui <strong>reste</strong> ?</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">189 = 10 × 18 + 9</span> : il faut <strong>19</strong> pages. <span class=\"nw\">75 = 6 × 12 + 3</span> : <strong>12</strong> boîtes pleines.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"probdiv\"></div></section><section class=\"ecran\"><h2>6. La division posée <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/division/potence.svg\" alt=\"612 ÷ 6 posée : 102\"></p>\n<p>Partage d&#39;abord les <strong>grandes</strong> unités.\nPas assez pour partager ? Écris <strong>0</strong>, puis échange.</p>\n<blockquote>\n<p><strong>Exemple.</strong> <span class=\"nw\">612 ÷ 6</span> : on commence par les centaines, donc le quotient a <strong>3 chiffres</strong>.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"divpose\"></div></section><section class=\"ecran\"><h2>7. Divisible par 2, 5 ou 10 <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/division/divisible.svg\" alt=\"Regarder le dernier chiffre\"></p>\n<p>Divisible : la division tombe juste.\nPour 2, 5 et 10, regarde <strong>le dernier chiffre</strong>.</p>\n<blockquote>\n<p><strong>Exemple.</strong> 13 n&#39;est pas divisible par 3. Le truc du dernier chiffre marche <strong>seulement</strong> pour 2, 5 et 10.</p>\n</blockquote>\n<div class=\"go-exo\" data-exos=\"divisible\"></div></section><p><em>Sources d&#39;inspiration : programme du cycle 2 (BO 2024 : partage et groupement, 24 élèves en équipes de 4, 189 photos, 75 œufs ; « ÷ » au CE2) et du cycle 3 (division euclidienne à diviseur à un chiffre au CM1 ; critères par 2, 5, 10). Textes et figures originaux.</em></p>\n","fractions":"\n<blockquote>\n<p>Une fraction parle de <strong>parts égales</strong>. Avec les fractions, on peut dire « un quart de la pizza », mesurer une longueur qui n&#39;est pas un nombre entier, et même placer de nouveaux nombres entre 0 et 1. Prends ton temps : ce chapitre est très important.</p>\n</blockquote>\n\n<h2>1. Des parts égales <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p>On partage un tout (une pizza, une bande, une tablette) en parts <strong>égales</strong>.</p>\n<ul>\n<li>Partagé en <strong>2</strong> parts égales : chaque part est <strong>un demi</strong> (la moitié).</li>\n<li>En <strong>3</strong> : un <strong>tiers</strong>. En <strong>4</strong> : un <strong>quart</strong>. En 5 : un <strong>cinquième</strong>. En 8 : un <strong>huitième</strong>. En 10 : un <strong>dixième</strong>.</li>\n</ul>\n<p><img src=\"figures/fractions/quart.svg\" alt=\"Un quart : oui, non, oui\"></p>\n<blockquote>\n<p>⚠ <strong>Les parts doivent être égales.</strong> Si on coupe un disque en 4 morceaux de tailles différentes, un morceau n&#39;est <strong>pas</strong> un quart.<br>\nLes parts grisées n&#39;ont pas besoin d&#39;être côte à côte, et une même fraction peut se dessiner de plusieurs façons.<br></p>\n</blockquote>\n\n<h2>2. Lire et écrire une fraction <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/fractions/huitiemes.svg\" alt=\"Trois huitièmes de la bande\"></p>\n<p>La bande est partagée en <strong>8</strong> parts égales, on en prend <strong>3</strong>. On écrit <strong><span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">8</span></span></strong> et on lit « <strong>trois huitièmes</strong> ».</p>\n<ul>\n<li>Le nombre du <strong>bas</strong> est le <strong>dénominateur</strong> : il dit <strong>en combien de parts égales</strong> on partage.</li>\n<li>Le nombre du <strong>haut</strong> est le <strong>numérateur</strong> : il dit <strong>combien de parts</strong> on prend.</li>\n</ul>\n<p><strong>Pourquoi c&#39;est logique ?</strong> <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">8</span></span>, c&#39;est <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">8</span></span> + <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">8</span></span> + <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">8</span></span> : « trois fois un huitième ». Et <span class=\"fr\"><span class=\"fr-n\">8</span><span class=\"fr-d\">8</span></span>, c&#39;est <strong>toutes</strong> les parts : c&#39;est le tout, donc <strong><span class=\"fr\"><span class=\"fr-n\">8</span><span class=\"fr-d\">8</span></span> = 1</strong>.</p>\n<blockquote>\n<p>⚠ Pour le dénominateur, compte <strong>toutes</strong> les parts (grisées et blanches), pas seulement les blanches.<br></p>\n</blockquote>\n\n<h2>3. Comparer des fractions <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><strong>Même dénominateur.</strong> Les parts ont la même taille : celui qui en a le plus a le plus. <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">5</span></span> &lt; <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">5</span></span>.</p>\n<p><strong>Numérateur 1 (ou même numérateur).</strong> Plus on partage, plus les parts sont <strong>petites</strong> :</p>\n<p><img src=\"figures/fractions/comparer.svg\" alt=\"1/3 est plus grand que 1/6\"></p>\n<p><span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">3</span></span> &gt; <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">6</span></span>, même si 3 &lt; 6 ! De même, <span class=\"fr\"><span class=\"fr-n\">5</span><span class=\"fr-d\">12</span></span> &lt; <span class=\"fr\"><span class=\"fr-n\">5</span><span class=\"fr-d\">8</span></span> : des douzièmes sont plus petits que des huitièmes.</p>\n<p><strong>Un dénominateur multiple de l&#39;autre</strong> <span class=\"lv lv-CE2\">CE2</span>. Pour comparer <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">12</span></span> et <span class=\"fr\"><span class=\"fr-n\">5</span><span class=\"fr-d\">6</span></span>, on transforme : <span class=\"fr\"><span class=\"fr-n\">5</span><span class=\"fr-d\">6</span></span> = <span class=\"fr\"><span class=\"fr-n\">10</span><span class=\"fr-d\">12</span></span>. Et <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">12</span></span> &lt; <span class=\"fr\"><span class=\"fr-n\">10</span><span class=\"fr-d\">12</span></span>.</p>\n<p><strong>Plus grand ou plus petit que 1 ?</strong> <span class=\"lv lv-CM1\">CM1</span> Si le haut est plus petit que le bas, la fraction est plus petite que 1 (<span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span>). Sinon, elle est plus grande que 1 ou égale (<span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">4</span></span>, <span class=\"fr\"><span class=\"fr-n\">4</span><span class=\"fr-d\">4</span></span>).</p>\n\n<h2>4. Ajouter et enlever des fractions <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/fractions/somme.svg\" alt=\"2/5 + 1/5 = 3/5\"></p>\n<p><strong>Pourquoi le dénominateur ne change pas ?</strong> On compte des cinquièmes, comme on compterait des billes : 2 cinquièmes + 1 cinquième = <strong>3 cinquièmes</strong>. On n&#39;additionne <strong>pas</strong> les dénominateurs.</p>\n<ul>\n<li><span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">3</span></span> − <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">3</span></span> = <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">3</span></span>.</li>\n<li><span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">5</span></span> + <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">5</span></span> = <span class=\"fr\"><span class=\"fr-n\">5</span><span class=\"fr-d\">5</span></span> = <strong>1</strong> (le tout).</li>\n<li><strong>Le complément.</strong> Lucie colorie <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">10</span></span> d&#39;une figure en bleu, et le reste en rouge. Le tout, c&#39;est <span class=\"fr\"><span class=\"fr-n\">10</span><span class=\"fr-d\">10</span></span>. Rouge : <span class=\"fr\"><span class=\"fr-n\">10</span><span class=\"fr-d\">10</span></span> − <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">10</span></span> = <strong><span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">10</span></span></strong>.</li>\n<li><span class=\"lv lv-CE2\">CE2</span> Avec un dénominateur multiple de l&#39;autre, on transforme d&#39;abord : <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">2</span></span> + <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">4</span></span> = <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">4</span></span> + <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">4</span></span> = <strong><span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span></strong>.</li>\n<li><span class=\"lv lv-CM2\">CM2</span> 3 × <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">5</span></span> = <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">5</span></span> + <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">5</span></span> + <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">5</span></span> = <strong><span class=\"fr\"><span class=\"fr-n\">6</span><span class=\"fr-d\">5</span></span></strong>.</li>\n</ul>\n<blockquote>\n<p>⚠ <strong>Piège.</strong> <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">5</span></span> + <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">5</span></span> = <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">10</span></span> ? Non ! Ce sont des cinquièmes : <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">5</span></span>.<br></p>\n</blockquote>\n\n<h2>5. Des fractions égales <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/fractions/egales.svg\" alt=\"3/4 = 6/8\"></p>\n<p><span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span> et <span class=\"fr\"><span class=\"fr-n\">6</span><span class=\"fr-d\">8</span></span> couvrent <strong>la même longueur</strong>. Pourquoi ? On a fait des parts <strong>2 fois plus petites</strong>, mais on en prend <strong>2 fois plus</strong>.</p>\n<blockquote>\n<p><strong>La règle :</strong> on peut <strong>multiplier</strong> le haut et le bas par le <strong>même</strong> nombre. <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">2</span></span> = <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">4</span></span> = <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">6</span></span> = <span class=\"fr\"><span class=\"fr-n\">5</span><span class=\"fr-d\">10</span></span>.<br>\n⚠ <strong>Piège.</strong> On ne peut pas <strong>ajouter</strong> le même nombre en haut et en bas : <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">2</span></span> n&#39;est pas égal à <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">3</span></span>.<br></p>\n</blockquote>\n\n<h2>6. La fraction est un nombre : la demi-droite <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p>On partage l&#39;<strong>unité</strong> (de 0 à 1) en parts égales. Avec 4 parts, chaque intervalle vaut <strong><span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">4</span></span></strong>.</p>\n<p><img src=\"figures/fractions/droite.svg\" alt=\"7/4 sur la demi-droite\"></p>\n<p>Pour placer <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">4</span></span>, on avance de <strong>7 intervalles</strong> de <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">4</span></span> depuis 0. On dépasse 1 : <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">4</span></span> est plus grand que 1.</p>\n<blockquote>\n<p>⚠ Compte les <strong>intervalles</strong> (les espaces), pas les traits. Et le dénominateur, c&#39;est le nombre de parts <strong>dans une unité</strong> (de 0 à 1), pas sur toute la droite.<br></p>\n</blockquote>\n\n<h2>7. Plus grand que 1 : entier + fraction <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><span class=\"fr\"><span class=\"fr-n\">4</span><span class=\"fr-d\">4</span></span> = 1. Donc <strong><span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">4</span></span> = <span class=\"fr\"><span class=\"fr-n\">4</span><span class=\"fr-d\">4</span></span> + <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span> = 1 + <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span></strong>. Et <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">4</span></span> est entre 1 et 2.\nDans l&#39;autre sens : <strong>2 + <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">5</span></span></strong> = <span class=\"fr\"><span class=\"fr-n\">10</span><span class=\"fr-d\">5</span></span> + <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">5</span></span> = <strong><span class=\"fr\"><span class=\"fr-n\">13</span><span class=\"fr-d\">5</span></span></strong> (car 2 = <span class=\"fr\"><span class=\"fr-n\">10</span><span class=\"fr-d\">5</span></span>).</p>\n<p><strong>Comment faire vite ?</strong> Combien de fois le dénominateur dans le numérateur ? 7 = 1 × 4 + 3 : donc <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">4</span></span> = 1 + <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span>. C&#39;est une division avec reste !</p>\n\n<h2>8. Fraction d&#39;une quantité <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><strong>Un tiers de 12 billes</strong> : on partage 12 en 3 parts égales : 12 ÷ 3 = <strong>4 billes</strong>.\n<strong>Deux tiers de 12 €</strong> : un tiers, c&#39;est 4 €. Deux tiers, c&#39;est <strong>2 fois plus</strong> : 8 €.\n<strong>Trois quarts de 100 m</strong> : 100 ÷ 4 = 25, puis 25 × 3 = <strong>75 m</strong>.</p>\n<p><strong>Pourquoi ça marche ?</strong> Le dénominateur dit en combien on partage (on divise), le numérateur dit combien de parts on prend (on multiplie).</p>\n<blockquote>\n<p>⚠ Ne t&#39;arrête pas à un quart quand on demande trois quarts !<br></p>\n</blockquote>\n\n<h2>Ce qu&#39;il faut retenir</h2>\n<ul>\n<li>Une fraction parle de parts <strong>égales</strong>. En bas : en combien on partage. En haut : combien on en prend.</li>\n<li>Plus on partage, plus les parts sont petites : <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">3</span></span> &gt; <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">6</span></span>.</li>\n<li>On ajoute des parts de même taille : <span class=\"fr\"><span class=\"fr-n\">2</span><span class=\"fr-d\">5</span></span> + <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">5</span></span> = <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">5</span></span>. Le dénominateur ne change pas.</li>\n<li>On peut multiplier le haut et le bas par le même nombre : <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span> = <span class=\"fr\"><span class=\"fr-n\">6</span><span class=\"fr-d\">8</span></span>.</li>\n<li>Une fraction est un nombre : elle a sa place sur la demi-droite. <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">4</span></span> = 1 + <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span>.</li>\n<li><span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span> de 100 : 100 ÷ 4, puis × 3.</li>\n</ul>\n<p><em>Sources d&#39;inspiration : programme du cycle 2 (BO 2024 : fractions d&#39;un tout au CE1, dénominateurs 2, 3, 4, 5, 6, 8, 10 ; <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">3</span></span> &gt; <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">6</span></span> ; <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">8</span></span> = <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">8</span></span> + <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">8</span></span> + <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">8</span></span> ; complément de <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">10</span></span> ; CE2 : <span class=\"fr\"><span class=\"fr-n\">6</span><span class=\"fr-d\">8</span></span> = <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">4</span></span>, bande-unité, dénominateurs ≤ 12, <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">12</span></span> et <span class=\"fr\"><span class=\"fr-n\">5</span><span class=\"fr-d\">6</span></span>) et du cycle 3 (CM1 ≤ 20, CM2 ≤ 60, fractions supérieures à 1, fraction d&#39;une quantité). Méthode inspirée des bandes de Singapour, textes et figures originaux.</em></p>\n","decimaux":"\n<blockquote>\n<p>Tu connais déjà les <strong>fractions</strong>. Ici, on regarde les fractions spéciales qui partagent en <strong>10</strong>, <strong>100</strong> ou <strong>1 000</strong>. Avec elles, on invente une écriture plus courte : le nombre <strong>à virgule</strong>.</p>\n</blockquote>\n\n<h2>1. Du dixième à l&#39;écriture à virgule <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p>On partage une unité en <strong>10</strong> parts égales : chaque part est <strong>un dixième</strong>, <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">10</span></span>.\nOn partage un dixième en <strong>10</strong> : chaque part est <strong>un centième</strong>, <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">100</span></span>.\n<span class=\"lv lv-CM2\">CM2</span> On partage encore : <strong>un millième</strong>, 1/1000.</p>\n<p><strong>Relations à retenir.</strong> 1 = <span class=\"fr\"><span class=\"fr-n\">10</span><span class=\"fr-d\">10</span></span> = <span class=\"fr\"><span class=\"fr-n\">100</span><span class=\"fr-d\">100</span></span>. Et <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">10</span></span> = <span class=\"fr\"><span class=\"fr-n\">10</span><span class=\"fr-d\">100</span></span>. <span class=\"lv lv-CM2\">CM2</span> <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">100</span></span> = 10/1000.</p>\n<p><img src=\"figures/decimaux/decompo.svg\" alt=\"2,37 = 2 + 3/10 + 7/100\"></p>\n<p>Pour écrire plus vite 2 + <span class=\"fr\"><span class=\"fr-n\">3</span><span class=\"fr-d\">10</span></span> + <span class=\"fr\"><span class=\"fr-n\">7</span><span class=\"fr-d\">100</span></span>, on invente un <strong>codage</strong> : <strong>2,37</strong>.</p>\n<ul>\n<li>La <strong>virgule</strong> montre où s&#39;arrêtent les <strong>unités</strong>.</li>\n<li>Le chiffre juste après la virgule : les <strong>dixièmes</strong>.</li>\n<li>Le suivant : les <strong>centièmes</strong>. <span class=\"lv lv-CM2\">CM2</span> Puis les <strong>millièmes</strong>.</li>\n</ul>\n<p>On lit 2,37 : « <strong>deux et trente-sept centièmes</strong> », ou « deux unités, trois dixièmes et sept centièmes ».</p>\n<p><strong>Pourquoi ça marche ?</strong> C&#39;est exactement comme pour les entiers : chaque colonne vaut <strong>10 fois moins</strong> que celle de gauche. Les dixièmes sont 10 fois plus petits que les unités, les centièmes 10 fois plus petits que les dixièmes.</p>\n<blockquote>\n<p>⚠ <strong>La partie après la virgule n&#39;est pas « un autre entier ».</strong> Dans 2,37, le « 37 » veut dire 37 <strong>centièmes</strong>, pas trente-sept unités. 2,37 = <span class=\"fr\"><span class=\"fr-n\">237</span><span class=\"fr-d\">100</span></span>.<br>\n<strong>Les zéros à droite ne changent pas la valeur :</strong> 2,5 = 2,50 = 2,500. On peut les ajouter pour comparer plus facilement.<br></p>\n</blockquote>\n\n<h2>2. Comparer, ranger, encadrer <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/decimaux/comparer.svg\" alt=\"2,5 est plus grand que 2,37\"></p>\n<p><strong>Comment comparer 2,5 et 2,37 ?</strong></p>\n<ol>\n<li>Même partie entière : 2 = 2.</li>\n<li>Regarde les <strong>dixièmes</strong> : 5 dixièmes &gt; 3 dixièmes. Donc <strong>2,5 &gt; 2,37</strong>.</li>\n</ol>\n<p>Astuce : écris le même nombre de chiffres après la virgule : 2,50 et 2,37. Maintenant tu compares 50 centièmes et 37 centièmes.</p>\n<blockquote>\n<p>⚠ <strong>Le grand piège.</strong> « 2,37 &gt; 2,5 parce que 37 &gt; 5 » : <strong>faux</strong> ! Tu compares des <strong>dixièmes</strong> à des <strong>centièmes</strong>. Ce n&#39;est pas la même taille de part.<br>\nAutre piège : 2,15 et 2,9. Les dixièmes : 1 &lt; 9, donc <strong>2,15 &lt; 2,9</strong>.<br></p>\n</blockquote>\n<p><strong>Encadrer.</strong> 17,48 est entre 17 et 18. Au dixième près : entre 17,4 et 17,5.\n<strong>Intercaler.</strong> Un nombre entre 1,9 et 2 ? Par exemple 1,95.</p>\n<p><strong>Partie entière et arrondi</strong> <span class=\"lv lv-CM1\">CM1</span>. La partie entière de 5,78 est <strong>5</strong>. L&#39;arrondi à l&#39;entier : on regarde le chiffre des dixièmes. ≥ 5 → on monte (5,78 → <strong>6</strong>). &lt; 5 → on garde (5,32 → <strong>5</strong>). 3,5 → <strong>4</strong>.</p>\n\n<h2>3. La demi-droite graduée décimale <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/decimaux/droite.svg\" alt=\"Zoom entre 2 et 3\"></p>\n<p>Entre 2 et 3, on peut <strong>zoomer</strong> : on repartage l&#39;intervalle en <strong>10</strong> dixièmes : 2,0 · 2,1 · 2,2 · … · 2,9 · 3,0.\nEntre 2,3 et 2,4, on peut encore zoomer en <strong>centièmes</strong> : 2,30 · 2,31 · … · 2,40.</p>\n<p><strong>Pourquoi ça marche ?</strong> Chaque intervalle d&#39;une unité contient 10 dixièmes, chaque dixième contient 10 centièmes : c&#39;est toujours la base dix.</p>\n\n<h2>4. Addition et soustraction de décimaux <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/decimaux/aligne.svg\" alt=\"Aligne les virgules\"></p>\n<p>Pour additionner ou soustraire, on <strong>aligne les virgules</strong> : les unités sous les unités, les dixièmes sous les dixièmes, les centièmes sous les centièmes.\nEnsuite, on calcule <strong>colonne par colonne</strong>, exactement comme avec les entiers. La retenue, c&#39;est toujours un échange de 10 contre 1 de la colonne de gauche.</p>\n<p>Exemple : 2,5 + 1,25. On écrit 2,50 + 1,25 = <strong>3,75</strong>.</p>\n<blockquote>\n<p>⚠ <strong>N&#39;aligne pas à droite.</strong> Si tu poses 2,5 + 1,25 en alignant les derniers chiffres, tu additionnes des dixièmes avec des centièmes : le résultat est faux.<br></p>\n</blockquote>\n\n<h2>5. × 10, × 100, ÷ 10 <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/decimaux/glisse.svg\" alt=\"Glisse-nombres\"></p>\n<p><strong>× 10</strong> : chaque chiffre prend une valeur <strong>10 fois plus grande</strong>. Les dixièmes deviennent des unités, les centièmes des dixièmes… Les chiffres <strong>glissent d&#39;un rang vers la gauche</strong> (la virgule, elle, reste à sa place pour séparer les unités).\n72,41 × 10 = <strong>724,1</strong>.</p>\n<p><strong>× 100</strong> : glissement de <strong>deux</strong> rangs. <strong>÷ 10</strong> : glissement d&#39;un rang vers la <strong>droite</strong> (les unités deviennent des dixièmes).</p>\n<blockquote>\n<p>⚠ « Ajouter un zéro » : ça marche pour les <strong>entiers</strong> (7 × 10 = 70), mais <strong>pas</strong> pour les décimaux. 7,2 × 10 n&#39;est <strong>pas</strong> 7,20 : c&#39;est <strong>72</strong>.<br></p>\n</blockquote>\n\n<h2>6. Décimal × entier <span class=\"lv lv-CM2\">CM2</span></h2>\n<p>Pour calculer 7 × 46,55 €, on peut poser la multiplication comme avec les entiers, <strong>sans la virgule</strong> : 7 × 4655 = 32 585.\nPuis on remet la virgule : 46,55 a <strong>2</strong> chiffres après la virgule, donc le produit aussi : <strong>325,85 €</strong>.</p>\n<p><strong>Pourquoi ça marche ?</strong> 46,55 = 4655/100, donc 7 × 46,55 = 7 × 4655 / 100. On divise le produit entier par 100 en plaçant la virgule.</p>\n<p>Vérifie l&#39;ordre de grandeur : 7 × 50 ≈ 350, et 325,85 est bien autour de 350.</p>\n\n<h2>7. Division décimale <span class=\"lv lv-CM2\">CM2</span></h2>\n<p>On sait déjà partager des entiers (chapitre 4). Ici, on continue la division <strong>après la virgule</strong>.</p>\n<p>Exemple : 45 ÷ 6.</p>\n<ul>\n<li>45 = 6 × 7 + 3, il reste 3.</li>\n<li>On ajoute une virgule au quotient et un 0 au reste : 30 dixièmes ÷ 6 = 5. Donc <strong>7,5</strong>.</li>\n</ul>\n<p><img src=\"figures/decimaux/divdec.svg\" alt=\"45 ÷ 6 = 7,5\"></p>\n<p><strong>Pourquoi ça marche ?</strong> 3 unités = 30 dixièmes. On échange le reste contre des unités 10 fois plus petites, comme on le faisait déjà colonne par colonne.</p>\n<p>On peut aussi diviser un décimal : 8,4 ÷ 4 = <strong>2,1</strong>.</p>\n<blockquote>\n<p>⚠ N’arrête pas dès qu’il y a un reste : ajoute des 0 après la virgule et continue, tant que le programme te le demande (souvent jusqu’aux centièmes).<br>\nLe diviseur reste un nombre à <strong>un chiffre</strong> (2 à 9).<br></p>\n</blockquote>\n\n<h2>8. Problèmes</h2>\n<p>Avec les décimaux, on parle souvent de <strong>monnaie</strong> (euros, centimes) et de <strong>mesures</strong> (mètres, kilogrammes).</p>\n<ul>\n<li>Ethan a acheté 3,4 kg de pommes. Il a acheté 6 kg de fruits en tout. Quelle masse de poires ? → 6 − 3,4 = <strong>2,6 kg</strong>.</li>\n<li>Attention aux <strong>données inutiles</strong> (un prix ou une durée qui ne sert pas), et aux pièges « de plus » / « fois plus ».</li>\n</ul>\n<p>Tu écris le calcul en faisant glisser les nombres, comme dans les autres chapitres. Pas de schéma tout fait : c&#39;est toi qui choisis l&#39;opération.</p>\n","proportionnalite":"\n<blockquote>\n<p>Quand j&#39;achète <strong>3 fois plus</strong> de pains, je paie <strong>3 fois plus</strong>. C&#39;est ça, la <strong>proportionnalité</strong> ! Dans ce chapitre, tu vas apprendre à reconnaître ces situations, et à raisonner avec des phrases : « fois plus », « fois moins », « et encore ».</p>\n</blockquote>\n\n<h2>1. Le prix de plusieurs objets pareils <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p>Des tee-shirts coûtent 13 € chacun. Le prix de 6 tee-shirts ? C&#39;est <strong>6 fois 13 €</strong> : 6 × 13 = <strong>78 €</strong>.</p>\n<p>Tu sais déjà le faire avec la multiplication (chapitre 3) : des objets <strong>pareils</strong>, au <strong>même prix</strong>.</p>\n\n<h2>2. Fois plus, fois moins <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<blockquote>\n<p><strong>4 pains aux raisins coûtent 7 €. Quel est le prix de 12 pains aux raisins ?</strong><br></p>\n</blockquote>\n<p><img src=\"figures/proportionnalite/pains.svg\" alt=\"12 pains, c&#39;est 3 fois plus que 4 pains\"></p>\n<p>On raisonne avec une phrase :</p>\n<ul>\n<li>12 pains, c&#39;est <strong>3 fois plus</strong> que 4 pains (4 × 3 = 12).</li>\n<li>Donc je paie <strong>3 fois plus</strong> : 7 € × 3 = <strong>21 €</strong>.</li>\n</ul>\n<p><strong>Pas besoin de connaître le prix d&#39;un pain !</strong> (Ici, un pain coûterait 1,75 €, ce n&#39;est pas facile.)</p>\n<p><strong>Fois moins.</strong> Une pile de 400 feuilles mesure 40 mm. Une pile de 100 feuilles, c&#39;est <strong>4 fois moins</strong> de feuilles : elle est <strong>4 fois moins</strong> épaisse : 40 ÷ 4 = <strong>10 mm</strong>.</p>\n<blockquote>\n<p>⚠ <strong>Piège.</strong> « 4 pains → 7 €, donc 12 pains → 15 € (j&#39;ajoute 8 des deux côtés) » : <strong>faux</strong> ! On ne paie pas « 8 € de plus » parce qu&#39;on a « 8 pains de plus ». On multiplie par le même nombre.<br></p>\n</blockquote>\n\n<h2>3. Ajouter deux situations <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<blockquote>\n<p>5 cahiers coûtent 10 €. 3 cahiers coûtent 6 €. Combien coûtent 8 cahiers ?<br></p>\n</blockquote>\n<ul>\n<li>8 cahiers, c&#39;est <strong>5 cahiers et 3 cahiers</strong>.</li>\n<li>Donc je paie <strong>10 € et 6 €</strong> : 10 + 6 = <strong>16 €</strong>.</li>\n</ul>\n<p><strong>Pourquoi ça marche ?</strong> Si j&#39;achète les 5 cahiers, puis les 3 cahiers, j&#39;ai 8 cahiers, et j&#39;ai payé les deux prix.\nOn peut aussi <strong>enlever</strong> : 5 cahiers − 3 cahiers = 2 cahiers, donc 10 € − 6 € = 4 €.</p>\n\n<h2>4. Proportionnel ou pas ? <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p>Pour savoir, pose-toi la question : <strong>si je prends 2 fois plus d&#39;un côté, ai-je 2 fois plus de l&#39;autre ?</strong></p>\n<table>\n<thead>\n<tr>\n<th>Situation</th>\n<th>Proportionnel ?</th>\n<th>Pourquoi</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Le prix de tee-shirts au même prix</td>\n<td><strong>oui</strong></td>\n<td>2 fois plus de tee-shirts → 2 fois plus cher</td>\n</tr>\n<tr>\n<td>Les œufs d&#39;une recette de gâteaux</td>\n<td><strong>oui</strong></td>\n<td>2 fois plus de gâteaux → 2 fois plus d&#39;œufs</td>\n</tr>\n<tr>\n<td>La taille d&#39;un enfant selon son âge</td>\n<td><strong>non</strong></td>\n<td>à 10 ans, on ne mesure pas 2 fois plus qu&#39;à 5 ans</td>\n</tr>\n<tr>\n<td>Manège : 5 € d&#39;entrée + 2 € par tour</td>\n<td><strong>non</strong></td>\n<td>l&#39;entrée se paie <strong>une seule fois</strong></td>\n</tr>\n<tr>\n<td>« 3 melons pour le prix de 2 »</td>\n<td><strong>non</strong></td>\n<td>la promotion change tout</td>\n</tr>\n</tbody></table>\n<blockquote>\n<p>⚠ <strong>Le piège du manège.</strong> 3 tours coûtent 5 + 3 × 2 = 11 €. Mais 6 tours ne coûtent pas 22 € : ils coûtent 5 + 6 × 2 = <strong>17 €</strong>. Quand ce n&#39;est pas proportionnel, on ne peut pas faire « fois plus ».<br></p>\n</blockquote>\n\n<h2>Ce qu&#39;il faut retenir</h2>\n<ul>\n<li>Proportionnel : 2 fois plus d&#39;un côté → 2 fois plus de l&#39;autre (3 fois, 4 fois… pareil).</li>\n<li>Je raisonne avec des phrases : « 12 pains, c&#39;est 3 fois plus que 4 pains, donc je paie 3 fois plus ».</li>\n<li>Je peux aussi ajouter deux situations : 8 cahiers = 5 cahiers + 3 cahiers.</li>\n<li>Attention aux situations qui ne sont <strong>pas</strong> proportionnelles : un âge, une entrée fixe, une promotion.</li>\n</ul>\n<p><em>Sources d&#39;inspiration : programme du cycle 3 (CM1–CM2 : linéarité multiplicative et additive, raisonnements en langage naturel ; « 4 pains aux raisins coûtent 7 € » ; pas de tableau, pas de coefficient, pas de produit en croix au cours moyen) et du cycle 2 (« des tee-shirts coûtent 13 € chacun »). Textes et figures originaux.</em></p>\n","mesures":"\n<blockquote>\n<p>Mesurer, c&#39;est comparer à une <strong>unité</strong>. Ce chapitre est plus court : on relie les unités à la <strong>numération</strong> (des paquets de 10, de 100), on règle une horloge, on rend la monnaie, et on découvre le <strong>périmètre</strong> et l&#39;<strong>aire</strong>.</p>\n</blockquote>\n\n<h2>1. Unités et conversions <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p>Les préfixes disent combien de fois plus grand ou plus petit :</p>\n<ul>\n<li><strong>kilo</strong> = 1 000 (1 kg = 1 000 g, 1 km = 1 000 m)</li>\n<li><strong>centi</strong> = <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">100</span></span> (1 cm = <span class=\"fr\"><span class=\"fr-n\">1</span><span class=\"fr-d\">100</span></span> m, 100 cm = 1 m)</li>\n<li><strong>milli</strong> = 1/1000 (1 mm = 1/1000 m)</li>\n</ul>\n<p><img src=\"figures/mesures/unites.svg\" alt=\"Tableau des longueurs\"></p>\n<p><strong>Pourquoi ça marche ?</strong> Convertir, c&#39;est la même idée que la numération : 1 m = 100 cm, comme 1 centaine = 100 unités. On glisse les chiffres d&#39;un rang (ou de deux, ou de trois).</p>\n<blockquote>\n<p>⚠ Choisis une unité <strong>plausible</strong>. Une gomme ne pèse pas 3 kg. La hauteur d&#39;une porte n&#39;est pas 2 mm.<br>\nPour convertir, regarde si tu vas vers une <strong>plus petite</strong> unité (le nombre grossit) ou une <strong>plus grande</strong> (le nombre diminue).<br></p>\n</blockquote>\n\n<h2>2. La monnaie <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p>1 euro = 100 centimes. On écrit 3,50 € pour 3 euros et 50 centimes.\nPour rendre la monnaie : on calcule ce qui a été payé <strong>moins</strong> le prix.</p>\n<blockquote>\n<p>⚠ Si un article coûte 2,40 € et qu&#39;on donne 5 €, on rend <strong>2,60 €</strong>, pas 3 € ni 2,40 €.<br></p>\n</blockquote>\n\n<h2>3. L&#39;heure et les durées <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p><img src=\"figures/mesures/horloge.svg\" alt=\"Horloge\"></p>\n<p>La petite aiguille : les <strong>heures</strong>. La grande : les <strong>minutes</strong>.\n1 heure = <strong>60</strong> minutes (pas 100 !). Un quart d&#39;heure = 15 min. Une demi-heure = 30 min.</p>\n<p>Pour une durée entre 8 h 50 et 9 h 20 : de 8 h 50 à 9 h 00 = 10 min, puis + 20 min = <strong>30 min</strong>.</p>\n<blockquote>\n<p>⚠ 1 h 50 + 20 min n&#39;est <strong>pas</strong> 1 h 70. 50 + 20 = 70 min = 1 h 10 min, donc 1 h 50 + 20 min = <strong>2 h 10</strong>.<br></p>\n</blockquote>\n\n<h2>4. Le périmètre <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p>Le périmètre, c&#39;est la longueur du <strong>tour</strong>. Pour un polygone : on <strong>additionne</strong> les longueurs des côtés.\nPour un rectangle 8 cm sur 3 cm : 8 + 3 + 8 + 3 = <strong>22 cm</strong>. (Pas besoin de formule : on fait le tour.)</p>\n<blockquote>\n<p>⚠ Le périmètre n&#39;est <strong>pas</strong> l&#39;aire. Deux figures peuvent avoir la même aire et des périmètres différents.<br></p>\n</blockquote>\n\n<h2>5. L&#39;aire <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/mesures/aire.svg\" alt=\"Aire en carreaux\"></p>\n<p>L&#39;aire, c&#39;est « combien de place » la figure occupe. On compte les <strong>carreaux</strong>.\n1 cm² = l&#39;aire d&#39;un carré de 1 cm de côté.\nPour un rectangle : on peut compter les carreaux <strong>rangée par rangée</strong> : longueur × largeur.</p>\n<p><strong>Pourquoi ça marche ?</strong> 5 rangées de 3 carreaux, c&#39;est 5 × 3 = 15 carreaux : la multiplication des paquets (chapitre 3).</p>\n","geometrie":"\n<blockquote>\n<p>Ce chapitre est plus court. On apprend à <strong>reconnaître</strong> les figures, les angles droits, la <strong>symétrie</strong>, et les <strong>solides</strong>. Moins de calculs, plus d&#39;observation.</p>\n</blockquote>\n\n<h2>1. Se repérer sur un quadrillage <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span></h2>\n<p>Sur un quadrillage, on peut dire : « avance de 3 cases à droite, puis 2 vers le haut ». Chaque case a une place.</p>\n\n<h2>2. Les figures <span class=\"lv lv-CE1\">CE1</span> <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p><img src=\"figures/geometrie/carre.svg\" alt=\"Carré penché\"></p>\n<ul>\n<li><strong>Carré</strong> : 4 côtés égaux, 4 angles droits.</li>\n<li><strong>Rectangle</strong> : 4 angles droits, côtés opposés égaux.</li>\n<li><strong>Triangle</strong> : 3 côtés. Rectangle / isocèle / équilatéral selon les côtés et angles.</li>\n<li><strong>Cercle</strong> : tous les points à la même distance du centre.</li>\n</ul>\n<blockquote>\n<p>⚠ Un carré <strong>penché</strong> reste un carré ! Tourner une figure ne change pas ce qu&#39;elle est.<br></p>\n</blockquote>\n\n<h2>3. Angle droit, perpendiculaires, parallèles <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p>Un <strong>angle droit</strong> a la forme du coin d&#39;une feuille.\nDeux droites <strong>perpendiculaires</strong> se coupent en formant un angle droit.\nDeux droites <strong>parallèles</strong> ne se rencontrent jamais (comme les rails).</p>\n\n<h2>4. Symétrie axiale <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span> <span class=\"lv lv-CM2\">CM2</span></h2>\n<p><img src=\"figures/geometrie/symetrie.svg\" alt=\"Symétrie\"></p>\n<p>Une figure a un <strong>axe de symétrie</strong> si on peut la plier en deux parties qui se superposent.\nPour compléter une figure symétrique sur un quadrillage : chaque point a son jumeau, à la même distance de l&#39;autre côté de l&#39;axe.</p>\n<p>En <strong>CE2</strong> et <strong>CM1</strong>, les axes sont <strong>horizontaux</strong> ou <strong>verticaux</strong> (sur le quadrillage).\nEn <strong>CM2</strong>, on ajoute aussi les axes <strong>diagonaux</strong> (suivant les diagonales du quadrillage).</p>\n\n<h2>5. Les solides <span class=\"lv lv-CE2\">CE2</span> <span class=\"lv lv-CM1\">CM1</span></h2>\n<p><img src=\"figures/geometrie/cube.svg\" alt=\"Cube\"></p>\n<p>Un <strong>cube</strong> : 6 faces carrées, 12 arêtes, 8 sommets.\nUn <strong>pavé</strong> : 6 faces rectangles.\nUne <strong>pyramide</strong> : une base et des faces triangles qui se rejoignent au sommet.\nUn <strong>patron</strong> de cube, c&#39;est le cube déplié à plat (6 carrés bien arrangés).</p>\n"};
